import { PuzzlePage } from "./puzzle-page.ts";
import { expect, setup } from "#/e2e/base.ts";
import { solvePuzzle } from "#/e2e/helpers.ts";

// Stored Flash starts were generated by the same solver as solvePuzzle, so the
// shorter puzzle is solved by the rest of that solution. alice: 8 moves, 2 in
// the Flash start. laerke: 9 moves, 2.

Deno.test("turning on Flash explains it first", async () => {
  const { page, teardown } = await setup();
  try {
    const puzzlePage = await new PuzzlePage(page).goto("alice");
    await puzzlePage.flashSwitch.click();

    await expect(puzzlePage.flashDialog.heading).toBeVisible();
  } finally {
    await teardown();
  }
});

Deno.test("Flash stays on once accepted", async () => {
  const { page, teardown } = await setup();
  try {
    const puzzlePage = await new PuzzlePage(page).goto("alice");
    await puzzlePage.flashSwitch.click();
    await puzzlePage.flashDialog.turnOn();

    await expect(puzzlePage.flashSwitch).toHaveAttribute(
      "aria-checked",
      "true",
    );
  } finally {
    await teardown();
  }
});

Deno.test("Flash starts a shorter puzzle from zero moves", async () => {
  const { page, teardown } = await setup();
  try {
    const moves = await solvePuzzle("alice");
    const puzzlePage = await new PuzzlePage(page).goto("alice");
    await puzzlePage.flashSwitch.click();
    await puzzlePage.flashDialog.turnOn();
    await puzzlePage.solveByClicking(moves.slice(2, 3));
    await puzzlePage.startOverLink.click();

    await expect(puzzlePage.moveCount("00")).toBeVisible();
  } finally {
    await teardown();
  }
});

Deno.test("a new player who solves with Flash is asked for a name", async () => {
  const { page, teardown } = await setup();
  try {
    const moves = await solvePuzzle("alice");
    const puzzlePage = await new PuzzlePage(page).goto("alice");
    await puzzlePage.flashSwitch.click();
    await puzzlePage.flashDialog.turnOn();
    await puzzlePage.solveByClicking(moves.slice(2));

    await expect(puzzlePage.solutionDialog.usernameInput).toBeVisible();
  } finally {
    await teardown();
  }
});

Deno.test("a returning player who solves with Flash sees the shorter puzzle's celebration", async () => {
  const { page, asUser, teardown } = await setup();
  try {
    await asUser({ name: "e2eflashy" });
    const moves = await solvePuzzle("alice");
    const puzzlePage = await new PuzzlePage(page).goto("alice");
    await puzzlePage.flashSwitch.click();
    await puzzlePage.flashDialog.turnOn();
    await puzzlePage.solveByClicking(moves.slice(2));

    await expect(puzzlePage.celebrationDialog.heading).toHaveText(
      "Perfect — 6 moves!",
    );
  } finally {
    await teardown();
  }
});

Deno.test("a returning player's Flash solve stays off the leaderboard", async () => {
  const { page, asUser, teardown } = await setup();
  try {
    await asUser({ name: "e2eflash" });
    const moves = await solvePuzzle("laerke");
    const puzzlePage = await new PuzzlePage(page).goto("laerke");
    await puzzlePage.flashSwitch.click();
    await puzzlePage.flashDialog.turnOn();
    await puzzlePage.solveByClicking(moves.slice(2));
    const solutionsPage = await puzzlePage.celebrationDialog.clickSeeSolves();

    await expect(solutionsPage.solveByName("e2eflash")).not.toBeVisible();
  } finally {
    await teardown();
  }
});

Deno.test("without JavaScript — a player turns on Flash and solves", async () => {
  const { page, teardown } = await setup({ javaScriptEnabled: false });
  try {
    const moves = await solvePuzzle("alice");
    const puzzlePage = await new PuzzlePage(page).goto("alice");
    await puzzlePage.flashSwitch.click();
    await puzzlePage.flashDialog.turnOn();
    await puzzlePage.solveByClicking(moves.slice(2));

    await expect(puzzlePage.solutionDialog.heading).toBeVisible();
  } finally {
    await teardown();
  }
});

Deno.test("a returning player who keeps starting over is offered Flash", async () => {
  const { page, asUser, teardown } = await setup();
  try {
    await asUser({ name: "e2estuck", skillLevel: "beginner" });
    const moves = await solvePuzzle("alice");
    const puzzlePage = await new PuzzlePage(page).goto("alice");
    for (let i = 0; i < 3; i++) {
      await puzzlePage.solveByClicking(moves.slice(0, 1));
      await puzzlePage.startOverLink.click();
    }

    await expect(puzzlePage.flashNudge).toBeVisible();
  } finally {
    await teardown();
  }
});

Deno.test("a player who says not now to Flash isn't offered it again", async () => {
  const { page, asUser, teardown } = await setup();
  try {
    await asUser({ name: "e2enotnow", skillLevel: "beginner" });
    const moves = await solvePuzzle("alice");
    const puzzlePage = await new PuzzlePage(page).goto("alice");
    for (let i = 0; i < 3; i++) {
      await puzzlePage.solveByClicking(moves.slice(0, 1));
      await puzzlePage.startOverLink.click();
    }
    await puzzlePage.flashNudge.click();
    await puzzlePage.flashDialogNotNow.click();

    await expect(puzzlePage.flashNudge).not.toBeVisible();
  } finally {
    await teardown();
  }
});

Deno.test("a player who has answered the Flash dialog turns Flash on straight from the badge", async () => {
  const { page, teardown } = await setup();
  try {
    const puzzlePage = await new PuzzlePage(page).goto("alice");
    await puzzlePage.flashSwitch.click();
    await puzzlePage.flashDialogNotNow.click();
    await puzzlePage.flashSwitch.click();

    await expect(puzzlePage.flashSwitch).toHaveAttribute(
      "aria-checked",
      "true",
    );
  } finally {
    await teardown();
  }
});
